install:
if [ -x scripts/cloud-agent-install.sh ] || [ -f scripts/cloud-agent-install.sh ]; then
  bash scripts/cloud-agent-install.sh
else
  rustup update stable
  rustup default stable
  bash scripts/mcp-install.sh
  mkdir -p .cursor "$HOME/.cursor"
  cat > .cursor/mcp.json <<'EOF'
{
  "mcpServers": {
    "neural-sgdb": {
      "type": "stdio",
      "command": "bash",
      "args": ["${workspaceFolder}/scripts/mcp-server.sh"],
      "env": {"NEURAL_SGDB_DEFAULT_SCOPE": "project/neural-sgdb"}
    }
  }
}
EOF
  python3 -c 'import json; from pathlib import Path
p=Path.home()/".cursor"/"mcp.json"
d={"mcpServers":{}}
if p.exists():
  try: d=json.loads(p.read_text() or "{}")
  except Exception: pass
root=Path.cwd()
d.setdefault("mcpServers",{})["neural-sgdb"]={"type":"stdio","command":"bash","args":[str(root/"scripts"/"mcp-server.sh")],"env":{"NEURAL_SGDB_DEFAULT_SCOPE":"project/neural-sgdb"}}
p.write_text(json.dumps(d,indent=2)+"\n")
print("OK: merged", p)'
fi
